param([Parameter(Mandatory=$true)][string]$DeveloperLogin,[string]$RosterPath,[switch]$SharedTeamPackage,[string]$AdminKeyPath=(Join-Path $env:USERPROFILE '.ssh\g6_oracle'),[string]$InstallRoot=(Join-Path $env:LOCALAPPDATA "G6\RabbitMQ\$DeveloperLogin"))
$ErrorActionPreference='Stop';if($DeveloperLogin-notmatch'^g5_[a-z0-9][a-z0-9_-]{1,30}$'){throw 'Provide one G5 package label.'};if($SharedTeamPackage){if($DeveloperLogin-cne'g5_equipo'){throw 'The shared package label is fixed to g5_equipo.'}}else{$approved=@(Import-Csv -LiteralPath $RosterPath|Where-Object {$_.Login-ceq$DeveloperLogin-and$_.EstadoHomologacion-ceq'HOMOLOGADO'-and-not[string]::IsNullOrWhiteSpace($_.ReferenciaHomologacion)});if($approved.Count-ne 1-or[string]::IsNullOrWhiteSpace($approved[0].Nombre)){throw 'Smoke requires one named recipient with documentary homologation reference.'}};if(-not(Test-Path $AdminKeyPath)){throw 'Administrator SSH key is missing.'};if(-not(Test-Path (Join-Path $InstallRoot 'Test-G5DeveloperAccess.ps1'))){throw 'Install this G5 package on the central test PC first.'}
$remote='ubuntu@157.137.205.218';$command='sudo -n docker exec g6-po-rabbitmq-1 rabbitmqctl list_queues --vhost g6-productos-ofertas --no-table-headers name messages consumers'
function Get-QueueSnapshot { $out=& ssh.exe -i $AdminKeyPath -o IdentitiesOnly=yes -o BatchMode=yes $remote $command;if($LASTEXITCODE-ne 0){throw 'Could not obtain administrative queue snapshot; smoke aborted.'};$result=@{};foreach($line in $out){if($line-match'^\s*(po\.(?:ventas|promociones)\.q)\s+(\d+)\s+(\d+)\s*$'){$result[$Matches[1]]=@{Messages=[int]$Matches[2];Consumers=[int]$Matches[3]}}};foreach($q in @('po.ventas.q','po.promociones.q')){if(-not$result.ContainsKey($q)){throw "Queue $q missing from snapshot; smoke aborted."}};return $result }
$before=Get-QueueSnapshot;foreach($q in $before.Keys){if($before[$q].Messages-ne 0-or$before[$q].Consumers-ne 0){throw "Queue isolation precondition failed for $q; nothing published."}}
$runError=$null;try{$env:G5_SMOKE_ALLOW_SYNTHETIC_PUBLISH='1';& (Join-Path $InstallRoot 'Test-G5DeveloperAccess.ps1');if($LASTEXITCODE-ne 0){throw 'G5 AMQP smoke failed.'}}catch{$runError=$_}finally{$env:G5_SMOKE_ALLOW_SYNTHETIC_PUBLISH=$null;Start-Sleep -Seconds 3;$after=Get-QueueSnapshot;foreach($q in $after.Keys){if($after[$q].Messages-ne 0-or$after[$q].Consumers-ne 0){$runError="Postcheck failed for $q; do not purge, stop and inspect manually."}}}
if($runError){throw $runError};Write-Output 'PASS: administrative queue preflight/postcheck were empty with zero consumers; G5 AMQP smoke completed through shared SSH account g5_tunnel.'
